proc isCurrentAppBroadcasting*(self: AppBroadcastingMonitor): bool =
  ## Windows.Media.AppBroadcasting.AppBroadcastingMonitor.get_IsCurrentAppBroadcasting
  withIface(self.p, IAppBroadcastingMonitor, it):
    result = it.getValue(get_IsCurrentAppBroadcasting, bool)

proc onIsCurrentAppBroadcastingChanged*(self: AppBroadcastingMonitor,
                                        handler: EventHandler[AppBroadcastingMonitor, WinRtObject]
                                       ): EventRegistrationToken {.discardable.} =
  ## Windows.Media.AppBroadcasting.AppBroadcastingMonitor.add_IsCurrentAppBroadcastingChanged
  ## The token is what `removeIsCurrentAppBroadcastingChanged` takes.
  withIface(self.p, IAppBroadcastingMonitor, it):
    proc shim(a0: pointer, a1: pointer) =
      handler(borrow[AppBroadcastingMonitor](a0), borrow[WinRtObject](a1))
    let cb = newDelegate(IID_TypedEventHandler_2_AppBroadcastingMonitor_Object,
                         shim, event = true)
    try:
      check it.vtbl.add_IsCurrentAppBroadcastingChanged(it, cb, result.addr), "AppBroadcastingMonitor.add_IsCurrentAppBroadcastingChanged"
    finally:
      release(cb)

proc removeIsCurrentAppBroadcastingChanged*(self: AppBroadcastingMonitor, token: EventRegistrationToken) =
  withIface(self.p, IAppBroadcastingMonitor, it):
    check it.vtbl.remove_IsCurrentAppBroadcastingChanged(it, token), "AppBroadcastingMonitor.remove_IsCurrentAppBroadcastingChanged"

